const $=id=>document.getElementById(id),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=v=>v==null?'—':`${Math.floor(v/60)}:${String(Math.round(v%60)).padStart(2,'0')}`;
let study,selected,manifest,events=[],cursor=0,timer=null,memoryTab='checks';
function event(node,title,description,route=null,extra={}){return {node,title,description,route,...extra};}
function compileEvents(m){
 const out=[event('input','The target stays fixed.',`Frozen CAD: ${m.target_sha256.slice(0,16)}… Every candidate must produce this same part.`),event('cam','Build the reference plan.','The deterministic reference is a comparison point. Astra creates the subsequent CAM candidates.','input-cam')];
 function evaluate(row,label,slot){
  const start=out.length;
  out.push(event('tests',`${label}: test gate.`,row.stage==='simulated'?'Input integrity and fixed checks passed. The plan proceeds to stock removal.':'The checks screened this candidate before simulation.','cam-tests',{failed:row.stage!=='simulated'}));
  if(row.stage==='simulated')out.push(event('sim',row.result.passed?'The simulation passes.':'The simulation fails.',row.result.passed?`Actual swept-stock verification passed. Estimated machining time: ${row.result.estimated_time_seconds.toFixed(2)} seconds.`:row.result.issues.map(x=>x.description).join(' '),'tests-sim',{failed:!row.result.passed}));
  if(!row.result.passed){if(row.stage==='simulated')out.push(event('tests','Save the failure as a check.','The exact failed geometry is remembered. A feed-only repeat can be rejected before another simulation; changed geometry still needs full verification.','sim-tests',{failed:true,check_source:row.path}));out.push(event('cam','Repair the geometry first.','CAM receives the failed check and diagnosis. It can change the path, including intersecting-pocket cleanup.','tests-cam'));}
  for(let i=start;i<out.length;i++)out[i].playback=slot;
 }
 if(m.reference)evaluate(m.reference,'Reference','reference');
 for(const a of m.attempts){
  out.push(event('cam',`CAM candidate ${a.index+1}.`,a.proposal?.summary||'Build the next explicit tool movements.',null,{strategy:a.strategy,playback:'attempt-'+a.index}));evaluate(a,`Candidate ${a.index+1}`,'attempt-'+a.index);
  if(a.judge){const stop=a.judge.value.action==='stop';out.push(event('judge',stop?'Keep the best verified plan.':'A valid plan. Can it be faster?',a.judge.value.reason,'sim-judge'));
   if(!stop)out.push(event('cam','Save timing guidance.','The timing observation is saved before the next CAM request. The judge does not prescribe a design, operation or feed.','judge-cam',{timing_source:a.judge.evidence}));}
 }
 if(m.final_judge)out.push(event('judge','Evaluate the retained incumbent.',m.final_judge.value.reason,'sim-judge'));
 if(m.status!=='running')out.push(event('judge',m.best?'A finished part, with evidence.':'No verified plan within this budget.',m.best?`Best passing estimate ${m.best.result.estimated_time_seconds.toFixed(2)} seconds. Memory ${m.saved_memory_version??'pending'} persists for the next part.`:'This run remains failed. Its diagnosis is still saved for the next attempt.',null,{failed:!m.best}));
 return out;
}
let activePlayback='';
function renderEvent(){const e=events[cursor];if(!e)return;
 const row=study.parts.find(p=>p.id===selected);const slot=e.playback||events.slice(0,cursor+1).reverse().find(e=>e.playback)?.playback;
 const variant=row.playback_variants?.includes(slot)?slot:null;const key=selected+(variant?'--'+variant:'');
 if(activePlayback!==key&&row.playback_ready){activePlayback=key;$('machine').src=`housing.html?part=${key}&study=${encodeURIComponent(study.asset_namespace||'')}&embed=1`;}
 $('viewlabel').textContent=variant?`Actual ${slot==='reference'?'reference':'candidate '+(Number(slot.split('-')[1])+1)} stock replay · accelerated`:'Best verified machining replay · independent of event stepping';$('stage-title').textContent=e.title;$('stage-description').textContent=e.description;$('step-count').textContent=`EVENT ${cursor+1} / ${events.length} · RECORDED EXECUTION`;$('progress').style.width=`${(cursor+1)/events.length*100}%`;document.querySelectorAll('.node').forEach(n=>n.classList.remove('active','fail'));document.querySelectorAll('.routes path').forEach(n=>n.classList.remove('active'));$('n-'+e.node)?.classList.add('active');if(e.failed)$('n-'+e.node)?.classList.add('fail');if(e.route)$('r-'+e.route)?.classList.add('active');$('event-detail').textContent=e.strategy?`Feed ${e.strategy.cut_feed_mm_min} mm/min · Stepdown ${e.strategy.stepdown_mm} mm · Junction cleanup ${e.strategy.junction_cleanup?'ON':'OFF'}`:'';memories();}
function stop(){clearInterval(timer);timer=null;$('play').textContent='Play the loop';}
function next(){if(cursor<events.length-1){cursor++;renderEvent();}else stop();}
$('play').onclick=()=>{if(timer){stop();return;}if(cursor===events.length-1)cursor=0;renderEvent();$('play').textContent='Pause replay';timer=setInterval(next,2300);};$('step').onclick=()=>{stop();next();};
function memories(){const m=manifest?.feedback_memory||study?.memory||{},field=memoryTab==='checks'?'learned_checks':'speed_guidance',inherited=manifest?.loaded_memory?.[field]||[],sources=new Set([...inherited.map(r=>r.source),...events.slice(0,cursor+1).map(e=>memoryTab==='checks'?e.check_source:e.timing_source)]),rows=(m[field]||[]).filter(r=>sources.has(r.source));$('memory-version').textContent=`${rows.length} ${memoryTab==='checks'?'saved checks':'timing notes'}`;$('memories').innerHTML=rows.length?rows.map(r=>`<div class="memory"><small>${esc(r.id||r.part)}</small>${esc(r.semantics||r.text)}${r.issues?`<div class="micro">${esc(r.issues.map(i=>i.code).join(', '))}</div>`:''}</div>`).join(''):'<p class="micro">No saved entries in this run yet. The register fills from actual feedback.</p>';}
$('show-checks').onclick=()=>{memoryTab='checks';memories();};$('show-speed').onclick=()=>{memoryTab='speed';memories();};
async function select(id){stop();selected=id;manifest=await fetch('/api/study-run?part='+id).then(r=>r.json());if(!manifest.id)return;cursor=0;events=compileEvents(manifest);renderEvent();const row=study.parts.find(p=>p.id===id);$('partname').textContent=manifest.name;$('reference').textContent=manifest.reference?.result.passed?fmt(row.reference_seconds):'FAIL';$('best').textContent=fmt(row.best_seconds);$('reduction').textContent=row.reduction_percent==null?'—':row.reduction_percent.toFixed(1)+'%';$('run-status').textContent=manifest.status.toUpperCase()+' · memory '+(row.loaded_memory_version??0)+' → '+(row.saved_memory_version??'…');const link=`housing.html?part=${id}&study=${encodeURIComponent(study.asset_namespace||'')}`;$('fullscreen').href=link;$('raw').href='/api/study-run?part='+id;$('viewlabel').textContent=manifest.best?'Best verified machining replay · independent of event stepping':'Last failed machining replay · geometry not verified';if(!row.playback_ready)$('machine').src='about:blank';document.querySelectorAll('#parts button').forEach(b=>b.classList.toggle('active',b.dataset.part===id));const passing=[manifest.reference,...manifest.attempts].filter(a=>a?.result.passed),max=Math.max(1,...passing.map(a=>a.result.estimated_time_seconds));$('history').innerHTML=[manifest.reference,...manifest.attempts].filter(Boolean).map((a,i)=>`<div class="attempt"><span>${i?'CAM '+i:'Reference'}</span>${a.result.passed?`<span class="bar"><i style="width:${a.result.estimated_time_seconds/max*100}%"></i></span><b>${fmt(a.result.estimated_time_seconds)}</b>`:`<b class="failtext">FAIL · ${esc(a.result.issues[0]?.code)}</b>`}</div>`).join('');memories();}
async function load(){const audit=await fetch('/api/learned-check-audit').then(r=>r.json());if(audit.passed)$('check-audit').textContent=`Verified saved-check replay: feed-only repetition rejected in ${(audit.seconds*1000).toFixed(1)} ms. Full simulation was not invoked.`;study=await fetch('/api/study-results').then(r=>r.json());$('parts').innerHTML=study.catalog.map((p,i)=>{const r=study.parts.find(r=>r.id===p.id);return `<button data-part="${p.id}" class="${selected===p.id?'active':''}"><small>PART ${String(i+1).padStart(2,'0')} / ${esc(r?.status||'QUEUED')}</small><b>${esc(p.name)}</b><em>${r?.best_seconds!=null?fmt(r.best_seconds)+' · VERIFIED':r?.status==='running'?'RUNNING':'—'}</em></button>`;}).join('');document.querySelectorAll('#parts button').forEach(b=>b.onclick=()=>select(b.dataset.part));if(!selected){const p=study.parts.find(p=>p.id==='02-hydraulic-manifold'&&p.playback_ready)||study.parts.find(p=>p.playback_ready)||study.parts[0];if(p)await select(p.id);}}
load().catch(e=>$('stage-description').textContent=e.message);
